INSERT INTO feature VALUES('documentation-comments','attributes','Documentation comments','attributes','implemented','ordinary',NULL,'`///` runs and `doc` attributes read as one documentation text with its links resolved, a link to a label the run''s footer line `[label]: target` defines resolving to that line, shown on hover, each link to a declaration followed by its reference line `[name]: <file URI>#L<line>`, which a hover and a `gandr doc` page write; a module''s documentation, nested modules included, is filed under the module form and hovers on its name; a source''s `//!` run documents the file and hovers on its import.','surface-lowering surface-parser surface-session surface-lsp','corpus/model/attributes/doc-comments.gandr corpus/model/include/monoid.gandr','corpus/model/attributes/doc-comments.gandr',NULL);
